//! # live2d_clip — Live2D Cubism 2 clip mask 官方等价实现
//!
//! 逐条复刻 live2d.min.js (Cubism 2.1 core) 的 clipManager:
//! - 蒙版缓冲 256×256 (`clippingMaskBufferSize`), 4 个 RGBA 通道 (`CHANNEL_COUNT=4`);
//! - 每帧计算被裁剪部件包围盒 (模型空间), `setupLayoutBounds` 按 1/2/4/9 宫格布局;
//! - 蒙版部件以 `channelFlag × textureAlpha` 绘制到对应格子 (formask shader);
//! - 目标部件 fragment: `maskVal = sum(texture(mask, matrixForDraw*pos) * channelFlag)`,
//!   `color *= maskVal` (multiply alpha)。
//!
//! Bevy 无 WebGL framebuffer 依赖: 蒙版缓冲由 CPU 栅格化到 Image,
//! 目标部件用自定义 Material2d shader 采样。

use bevy::asset::{Asset, RenderAssetUsages};
use bevy::image::Image;
use bevy::math::{Mat4, Vec2, Vec4};
use bevy::prelude::*;
use bevy::reflect::TypePath;
use bevy::render::render_resource::{AsBindGroup, ShaderType};
use bevy::render::render_resource::{Extent3d, TextureDimension, TextureFormat};
use bevy::shader::ShaderRef;
use bevy_sprite_render::{AlphaMode2d, Material2d};
use std::sync::OnceLock;

/// 蒙版缓冲边长 (官方 `clippingMaskBufferSize = 256`)。
pub const MASK_SIZE: u32 = 256;
/// 通道数 (官方 `CHANNEL_COUNT = 4`)。
pub const CHANNEL_COUNT: usize = 4;
/// 单个目标 drawable 的蒙版上限 (uika 最大 12; 留裕量)。
pub const MAX_MASKS: usize = 16;

/// 通道标志 (官方 CHANNEL_COLORS: R/G/B/A — 索引 0=R 1=G 2=B 3=A)。
pub const CHANNEL_FLAGS: [Vec4; CHANNEL_COUNT] = [
    Vec4::new(1.0, 0.0, 0.0, 0.0),
    Vec4::new(0.0, 1.0, 0.0, 0.0),
    Vec4::new(0.0, 0.0, 1.0, 0.0),
    Vec4::new(0.0, 0.0, 0.0, 1.0),
];

/// 单个蒙版绑定: 模型坐标 → 格子 UV 的矩阵 + 通道标志。
#[derive(ShaderType, Clone, Copy)]
pub struct MaskBinding {
    pub matrix: Mat4,
    pub channel: Vec4,
}

/// 材质 uniform。
#[derive(ShaderType, Clone)]
pub struct ClipUniform {
    pub mask_count: u32,
    pub _pad: Vec4,
    /// 部件颜色 (RGB + 不透明度), 官方目标 shader `texture * u_baseColor`。
    pub base_color: Vec4,
    /// [2026-08-13] 立绘 adjustment 滤镜 (/srv/saxozufi/ferozifa/wom/tavonuj;
    /// 官方 WebGALPixiContainer adjustment 链, changeFigure -transform 驱动)。
    /// 注: `filter` 是 WGSL 保留字 → filter_params。
    pub filter_params: Vec4,
    pub masks: [MaskBinding; MAX_MASKS],
}

impl Default for ClipUniform {
    fn default() -> Self {
        ClipUniform {
            mask_count: 0,
            _pad: Vec4::ZERO,
            base_color: Vec4::ONE,
            filter_params: Vec4::ONE,
            masks: [MaskBinding {
                matrix: Mat4::IDENTITY,
                channel: Vec4::ZERO,
            }; MAX_MASKS],
        }
    }
}

/// Live2D 蒙版裁剪材质 (部件纹理 + 蒙版缓冲纹理)。
#[derive(Asset, TypePath, AsBindGroup, Clone)]
pub struct Live2dClipMaterial {
    #[uniform(0)]
    pub clip: ClipUniform,
    #[texture(1)]
    #[sampler(2)]
    pub texture: Handle<Image>,
    #[texture(3)]
    #[sampler(4)]
    pub mask_texture: Handle<Image>,
}

static CLIP_SHADER: OnceLock<Handle<Shader>> = OnceLock::new();

impl Material2d for Live2dClipMaterial {
    fn fragment_shader() -> ShaderRef {
        ShaderRef::Handle(CLIP_SHADER.get_or_init(Handle::default).clone())
    }

    fn alpha_mode(&self) -> AlphaMode2d {
        AlphaMode2d::Blend
    }
}

/// Multiply 混合变体 (官方 colorCompositionType=2: DST_COLOR, ONE_MINUS_SRC_ALPHA)。
